const crypto = require('crypto');

const input = $input.first().json;
const method = (input.method || 'GET').toUpperCase();
const path = input.path;
const tenantId = input.tenant_id;
const idempotencyKey = input.idempotency_key;
const body = input.body || null;

const rawBody = body ? (typeof body === 'string' ? body : JSON.stringify(body)) : '';
const timestamp = Math.floor(Date.now() / 1000).toString();
const bodySha256 = crypto.createHash('sha256').update(rawBody, 'utf8').digest('hex');

const serviceId = 'n8n';
const canonical = [
  'v1',
  serviceId,
  tenantId,
  method,
  path,
  timestamp,
  idempotencyKey,
  bodySha256
].join('\n');

const secret = $env.SERVICE_HMAC_SECRET || '';
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex');

const headers = {
  'X-Service-Id': serviceId,
  'X-Tenant-ID': tenantId,
  'X-Timestamp': timestamp,
  'X-Idempotency-Key': idempotencyKey,
  'X-Signature': signature,
  'Content-Type': 'application/json'
};

return [{
  json: {
    url: 'http://backend:8000' + path,
    method: method,
    headers: headers,
    body: body,
    rawBody: rawBody
  }
}];
